import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT ?? 3000);
const select = db.prepare('SELECT * FROM jobs WHERE id = ?');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function err(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function bodyText(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const b = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += b.length;
    if (size > 1024 * 1024) throw new Error('body too large');
    chunks.push(b);
  }
  return Buffer.concat(chunks).toString('utf8');
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/') return err(res, 405, 'method_not_allowed', 'Method not allowed.');
  if (pathname === '/health') {
    if (req.method !== 'GET') return err(res, 405, 'method_not_allowed', 'Method not allowed.');
    const hb = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as { seen_at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: hb && Date.now() - Number(hb.seen_at) <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (req.method !== 'POST') return err(res, 405, 'method_not_allowed', 'Method not allowed.');
    const fields: { field: string; message: string }[] = [];
    const ct = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(ct)) fields.push({ field: 'Content-Type', message: 'Must be application/json.' });
    let raw: string;
    try { raw = await bodyText(req); } catch { return err(res, 400, 'invalid_request', 'Invalid request body.', [{ field: 'body', message: 'Request body is too large or unreadable.' }]); }
    let value: unknown;
    try { value = JSON.parse(raw); } catch { fields.push({ field: 'body', message: 'Must contain valid JSON.' }); }
    if (!value || typeof value !== 'object' || Array.isArray(value)) fields.push({ field: 'body', message: 'Must be a JSON object.' });
    const obj = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
    for (const k of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(k)) fields.push({ field: k, message: 'Unknown field.' });
    if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'Is required.' });
    else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else if (obj.input.length < 1 || obj.input.length > 1000 || !obj.input.trim()) fields.push({ field: 'input', message: 'Must be 1–1000 characters and not only whitespace.' });
    const steps = obj.steps === undefined ? 5 : obj.steps;
    const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
    if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'Must match ^[A-Za-z0-9_-]{1,128}$.' });
    if (fields.length) return err(res, 400, 'invalid_request', 'Request validation failed.', fields);
    const idemKey = typeof key === 'string' ? key : undefined;
    const payload = JSON.stringify({ input: obj.input, steps, failAttempts });
    if (idemKey !== undefined) {
      const previous = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(idemKey) as (Record<string, unknown> & { payload: string }) | undefined;
      if (previous) {
        if (previous.payload !== payload) return err(res, 409, 'idempotency_conflict', 'This idempotency key was used with a different payload.');
        return send(res, 200, toJob(previous));
      }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    try {
      db.exec('BEGIN IMMEDIATE');
      db.prepare('INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,completed,created_at,updated_at,available_at) VALUES(?,?,?,?,?,0,0,?,?,0)')
        .run(id, 'queued', obj.input as string, steps as number, failAttempts as number, now, now);
      if (idemKey !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(idemKey, payload, id);
      db.exec('COMMIT');
    } catch {
      try { db.exec('ROLLBACK'); } catch { /* transaction already closed */ }
      if (idemKey !== undefined) {
        const previous = db.prepare('SELECT i.payload, j.* FROM idempotency i JOIN jobs j ON j.id=i.job_id WHERE i.key=?').get(idemKey) as (Record<string, unknown> & { payload: string }) | undefined;
        if (previous) return previous.payload === payload ? send(res, 200, toJob(previous)) : err(res, 409, 'idempotency_conflict', 'This idempotency key was used with a different payload.');
      }
      return err(res, 500, 'internal_error', 'Could not create job.');
    }
    return send(res, 201, {
      id, status: 'queued', input: obj.input, steps, failAttempts, attempts: 0,
      progress: { completed: 0, total: steps }, result: null, error: null, createdAt: now, updatedAt: now,
    });
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (req.method !== 'GET') return err(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string; try { id = decodeURIComponent(match[1]!); } catch { return err(res, 404, 'not_found', 'Job not found.'); }
    const row = select.get(id) as Record<string, unknown> | undefined;
    return row ? send(res, 200, toJob(row)) : err(res, 404, 'not_found', 'Job not found.');
  }
  if (pathname.startsWith('/api/')) return err(res, 404, 'not_found', 'Route not found.');
  return err(res, 404, 'not_found', 'Route not found.');
});

server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, toJob } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row can only belong to a worker that has died: this process is the sole consumer.
db.prepare("UPDATE jobs SET status='queued', completed=0, available_at=0, updated_at=? WHERE status='running'").run(new Date().toISOString());
const heartbeat = db.prepare('INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at');
const get = db.prepare('SELECT * FROM jobs WHERE id=?');

async function processJob(id: string): Promise<void> {
  const row = get.get(id) as Record<string, unknown>;
  const job = toJob(row);
  for (let i = 1; i <= job.steps; i++) {
    await sleep(100);
    if (stopping) return;
    if (i === 1 && job.attempts <= job.failAttempts) {
      const now = new Date().toISOString();
      if (job.attempts >= 3) {
        db.prepare("UPDATE jobs SET status='failed',completed=0,error='transient failure',result=NULL,updated_at=? WHERE id=? AND status='running'").run(now, id);
      } else {
        db.prepare("UPDATE jobs SET status='queued',completed=0,available_at=?,updated_at=? WHERE id=? AND status='running'").run(Date.now() + 500, now, id);
      }
      return;
    }
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET completed=?,updated_at=? WHERE id=? AND status='running'").run(i, now, id);
  }
  const now = new Date().toISOString();
  db.prepare("UPDATE jobs SET status='completed',result=?,error=NULL,completed=steps,updated_at=? WHERE id=? AND status='running'")
    .run(JSON.stringify({ output: job.input.toUpperCase() }), now, id);
}

console.log('worker started');
while (!stopping) {
  heartbeat.run(Date.now());
  // Claim under an immediate transaction so simultaneous worker launches cannot take the same row.
  let id: string | undefined;
  try {
    db.exec('BEGIN IMMEDIATE');
    const next = db.prepare("SELECT id FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1").get(Date.now()) as { id: string } | undefined;
    if (next) {
      const now = new Date().toISOString();
      const changed = db.prepare("UPDATE jobs SET status='running',attempts=attempts+1,completed=0,result=NULL,error=NULL,updated_at=? WHERE id=? AND status='queued'").run(now, next.id);
      if (Number(changed.changes) > 0) id = next.id;
    }
    db.exec('COMMIT');
  } catch {
    try { db.exec('ROLLBACK'); } catch { /* no active transaction */ }
  }
  if (id) await processJob(id);
  else await sleep(100);
}
db.close();
console.log('worker stopped');
